        b.add(.ref(ty("spöb"), base: 0), 0, "soldAt", "Sold At", group: "Where Traded", help: "ID number of the stellar object where the commodity is sold. Set to 0 or -1 if unused.", count: 8, stride: 2, def: -1, opts: [.v("None", -1)])
        b.add(.ref(ty("spöb"), base: 0), 16, "boughtAt", "Bought At", group: "Where Traded", help: "ID number of the stellar object where the commodity is purchased. Set to 0 or -1 if unused.", count: 8, stride: 2, def: -1, opts: [.v("None", -1)])
        b.add(.i16, 32, "basePrice", "Base Price", group: "Economy", help: "The average price of the commodity (works much like the base prices for \"regular\" commodities)")
        b.add(.flags(.w16), 34, "flags", "Flags", group: "Economy", help: "Misc flag bits 0x0001 Tribbles flag - When in your cargo bay, the commodity multiplies like tribbles. 0x0002 Perishable - When in your cargo bay, the commodity gradually decays away.", bits: [.f(0x1, "Multiplies in cargo hold"), .f(0x2, "Decays in cargo hold")])
        b.add(.flags(.w16), 36, "scanMask", "Scan Mask", group: "Economy", help: "If this is an \"illegal\" cargo type, this is used in conjunction with the ScanMask field in the gövt resource.")
        b.add(.cString(64), 38, "lowercaseName", "Lowercase Name", group: "Names", help: "The lower-case string to display in the player-info dialog box, among other places, e.g. \"machine parts\".")
        b.add(.cString(64), 102, "abbreviation", "Status Bar Abbreviation", group: "Names", help: "The short string that is displayed in the player's status bar when the player is carrying jünk of this type, e.g. \"Parts\".")
        b.add(.ncb(.test, 255), 166, "buyOn", "BuyOn (NCB Test)", group: "Scripts", help: "Control bit test expression. This jünk will only be available to be bought when this expression evaluates true. Leave blank if unused.")
        b.add(.ncb(.test, 255), 421, "sellOn", "SellOn (NCB Test)", group: "Scripts", help: "Control bit test expression. This jünk will only be able to be sold when this expression evaluates true. Leave blank if unused.")
        return b.build(type: ty("jünk"), name: "Junk Commodity", related: [])
    }

