    static func makeRankSchema() -> ResourceSchema {
        var b = SchemaBuilder()
        b.add(.i16, 0, "weight", "Weight", group: "Rank", help: "The importance of this rank, relative to the other rank resources that might be active.")
        b.add(.ref(ty("gövt"), base: 0), 2, "affilGovt", "Govt Affiliation", group: "Rank", help: "The ID of the government affiliated with this rank.", def: -1, opts: [.v("None", -1)])
        b.add(.i16, 4, "priceMod", "Price Modifier (%)", group: "Rank", help: "Used to modify the prices of items and ships at planets owned by the affiliated government. A value of 100 equals 100% of original price (i.e. prices are unchanged).", def: 100)
        b.add(.i32, 6, "salary", "Salary", group: "Rank", help: "The number of credits that the affiliated government will pay the player, per day")
        b.add(.enumeration(.w32, signed: true), 10, "salaryCap", "Salary Cap", group: "Rank", help: "The maximum amount of money the player can have before the affiliated government stops paying the salary. Set to 0 or -1 if unused. (credits)", opts: [.v("Uncapped", 0)])
        b.add(.mask64, 14, "contribute", "Contribute", group: "Requirements", help: "Another 64 bits of Contribute values that kick in when the rank is active. These can be used to prevent the player from buying certain items or doing certain missions until achieving a certain rank, for example.")
        b.add(.flags(.w16), 22, "flags", "Flags", group: "Flags", help: "0x0001 Deactivate all other active ranks affiliated with this same govt when this rank is activated (excludes permanent ranks) 0x0002 Deactivate all other active ranks affiliated with this same govt when this rank is dea…", bits: [.f(0x1, "Drop other ranks of same govt when activated"), .f(0x2, "Drop other ranks of same govt when deactivated"), .f(0x4, "Drop if player disables/destroys a govt/allied ship"), .f(0x8, "Permanent, only removed by NCB statement"), .f(0x10, "Drop lower ranks of same govt when activated"), .f(0x20, "Drop lower ranks of same govt when deactivated"), .f(0x40, "Drop if player commits crime against govt"), .f(0x100, "Govt ships won’t attack player"), .f(0x200, "Player can always land on govt’s stellars"), .f(0x400, "Player can ask govt ships for battle assistance"), .f(0x800, "Govt and allies will always refuel/repair for free")])
        b.add(.cString(64), 24, "convName", "Conversation Name", group: "Names", help: "The rank name as used in conversation, through mission briefings and the <PRK> tag. If this is set to an empty string, the rank will never be used in conversation.")
        b.add(.cString(64), 88, "shortName", "Conversation Short Name", group: "Names", help: "The short rank named as used in conversation through mission briefings and the <PSR> tag. Behavior with an empty string is the same as for the ConvName field.")
        return b.build(type: ty("ränk"), name: "Rank", related: [])
    }

    static func makeRoidSchema() -> ResourceSchema {
        var b = SchemaBuilder()
        b.add(.i16, 0, "strength", "Strength", group: "Asteroid", help: "The strength of this asteroid type - this is equivalent to armor values for ships.", def: 100)
        b.add(.i16, 2, "spinRate", "Spin Rate", group: "Asteroid", help: "The frame advance rate of this asteroid type. A value of 100 is 30 frames per second (quite fast) - lower numbers are slower. (100 = 30 frames per second)", def: 100)
        b.add(.i16, 4, "yieldType", "Cargo Yield Type", group: "Yield", help: "Defines what the resource-boxes which are ejected from this asteroid type will contain: 0-5 This type of standard cargo 1000-1127 This type of jünk resource", def: -1, opts: [.v("None", -1), .v("Food", 0), .v("Industrial", 1), .v("Medical Supplies", 2), .v("Luxury Goods", 3), .v("Metal", 4), .v("Equipment", 5), .open("Junk", 1000, ty("jünk"), 128)])
        b.add(.i16, 6, "yieldQty", "Yield Quantity", group: "Yield", help: "The average resource yield of this type of asteroid. Zero will cause asteroids of this type to not spit out any resource-boxes when destroyed; (±50%)")
        b.add(.i16, 8, "partCount", "Destroy Particle Count", group: "Debris", help: "The number of particles that are thrown off when an asteroid of this type is destroyed.")
        b.add(.color, 10, "partColor", "Destroy Particle Color", group: "Debris", help: "The color of the particles, encoded the same as HTML colors. (00RRGGBB)")
        b.add(.ref(ty("röid"), base: 0), 14, "fragType1", "Fragment Type 1", group: "Fragments", help: "Asteroids can break up into some number of sub-asteroids when destroyed. If both of these fields are used, Nova will randomly pick between them for each sub-asteroid that is created.", def: -1, opts: [.v("None", -1)])
        b.add(.ref(ty("röid"), base: 0), 16, "fragType2", "Fragment Type 2", group: "Fragments", def: -1, opts: [.v("None", -1)])
        b.add(.i16, 18, "fragCount", "Fragment Count", group: "Fragments", help: "The average number of sub-asteroids (+/- 50%) to be generated when an asteroid of this type is destroyed (zero for none). (±50%)")
        b.add(.enumeration(.w16, signed: true), 20, "explodeType", "Explosion Type", group: "Fragments", help: "Type of explosion to show (0-63) when an asteroid of this type is destroyed. You can also add 1000 to the value of this field in the same manner as the ExplodeType field in the wëap resource.", def: -1, opts: [.v("None", -1), .r("Single Explosion", 0, 63, ty("bööm"), 128), .r("Explosion + Sparks", 1000, 1063, ty("bööm"), 128)])
        b.add(.i16, 22, "mass", "Mass", group: "Fragments", help: "Mass of this asteroid type (used when weapons hit asteroids)", def: 100)
        b.add(.blob(16), 24, "reserved24", "Reserved", group: "Reserved")
        return b.build(type: ty("röid"), name: "Asteroid", related: [])
    }

