    static func makeShipSchema() -> ResourceSchema {
        var b = SchemaBuilder()
        b.add(.i16, 0, "cargoSpace", "Cargo Capacity", group: "Performance", help: "Cargo capacity, in tons. Put a negative sign in front of this value if you want to prevent the player from purchasing mass expansions. (e.g.", def: 10, opts: [.open("Allow Mass Expansions", 0, nil, nil), .open("No Mass Expansions", -1, nil, 1)])
        b.add(.i16, 2, "shield", "Shield Strength", group: "Performance", help: "Shield strength.", def: 100, opts: [.open("Normal Shields", 0, nil, nil), .open("Super Shields (x5)", -1, nil, 1)])
        b.add(.i16, 4, "acceleration", "Acceleration", group: "Performance", help: "Acceleration magnitude. 300 is considered an average value. (300 = average)", def: 300)
        b.add(.i16, 6, "speed", "Top Speed", group: "Performance", help: "Top speed. 300 is also an average value here. (300 = average)", def: 300)
        b.add(.i16, 8, "turnRate", "Turn Rate", group: "Performance", help: "Turn rate. 10 ≈ 30°/sec.", def: 20)
        b.add(.i16, 10, "fuel", "Fuel Capacity", group: "Performance", help: "Fuel capacity. 100 = 1 jump.", def: 300)
        b.add(.i16, 12, "freeMass", "Available Space", group: "Performance", help: "Space available to add additional items and upgrades. Note that this is in addition to the space taken up by the ship’s stock weapons. (e.g. (tons)", def: 50)
        b.add(.i16, 14, "armor", "Armor Strength", group: "Performance", help: "Armor strength. (Ships with no armor will die on spawn.)", def: 100)
        b.add(.i16, 16, "shieldRecharge", "Shield Recharge Rate", group: "Performance", help: "Shield recharge speed, in number of shield points x1000 per frame. Bigger numbers here mean faster recharge - a value of 1000 is equal to 1 point per frame or 30 points per second.", def: 500)
        b.add(.ref(ty("wëap"), base: 0), 18, "weaponTypes", "Stock Weapon", group: "Stock Weapons", count: 4, stride: 2, def: -1, opts: [.v("None", -1)])
        b.add(.i16, 26, "weaponCounts", "Stock Weapon Count", group: "Stock Weapons", count: 4, stride: 2)
        b.add(.i16, 34, "ammoLoads", "Stock Ammo Load", group: "Stock Weapons", count: 4, stride: 2)
        b.add(.i16, 42, "maxGuns", "Maximum Fixed Guns", group: "Limits & Cost", help: "The ship’s maximum number of fixed guns, which are flagged in the WeapFlag field of the outf resource.", min: 0, def: 2)
        b.add(.i16, 44, "maxTurrets", "Maximum Turrets", group: "Limits & Cost", help: "The ship’s maximum number of turrets, which are flagged in the WeapFlag field of the outf resource.", min: 0, def: 0)
        b.add(.i16, 46, "techLevel", "Tech Level", group: "Limits & Cost", help: "What the technology level of the ship is. This ship will be available at all shipyards with a tech level of this value or higher. (The exception to this rule involves the SpecialTech fields of the spöb resource;", min: 0, def: 1)
        b.add(.i32, 48, "cost", "Cost", group: "Limits & Cost", def: 50000)
        b.add(.i16, 52, "deathDelay", "Death Delay (frames)", group: "Destruction", help: "The number of frames the ship \"disintegrates\" before finally exploding. 0-59 The ship disintegrates for this number of frames and then disappears in a single fireball.", def: 30)
        b.add(.i16, 54, "armorRecharge", "Armor Recharge Rate", group: "Destruction", help: "Armor recharge speed, in number of armor points x1000 per frame. Bigger numbers here mean faster recharge - a value of 1000 is equal to 1 point per frame or 30 points per second.", def: 0)
        b.add(.enumeration(.w16, signed: true), 56, "breakupExplosion", "Breakup Explosion", group: "Destruction", help: "Type of explosion to show (0-63) while the ship is breaking up, or -1 to not show any explosions until the ship is finished being destroyed.", def: -1, opts: [.v("None", -1), .r("Multiple Explosions", 0, 63, ty("bööm"), 128)])
        b.add(.enumeration(.w16, signed: true), 58, "finalExplosion", "Final Explosion", group: "Destruction", help: "Type of explosion to show (0-63) when the ship is completely destroyed. You can also add 1000 to the value of this field in the same manner as the ExplodeType field in the wëap resource.", def: 0, opts: [.v("None", -1), .r("Single Explosion", 0, 63, ty("bööm"), 128), .r("Explosion + Sparks", 1000, 1063, ty("bööm"), 128)])
        b.add(.i16, 60, "dispWeight", "Display Weight", group: "Identity", help: "The display weight of this ship type. Ships with a higher display weight are shown closer to the top of the shipyard dialog.", def: 100)
