        b.add(.enumeration(.w16, signed: true), 66, "inherentAI", "Inherent AI", group: "Identity", help: "What AI the ship uses when it's escorting the player. 1-4 Use this kind of AI.", def: 3, opts: [.v("Wimpy Trader", 1), .v("Brave Trader", 2), .v("Warship", 3), .v("Interceptor", 4)])
        b.add(.enumeration(.w16, signed: true), 68, "crew", "Crew Count", group: "Identity", help: "Number of crew members. Ships with 0 crew can't be boarded, nor can they capture any other ships.", def: 10, opts: [.v("Can’t be boarded", 0)])
