        b.add(.i16, 410, "reinfInterval", "Reinforcement Regen (days)", group: "Reinforcements", help: "The interval, in days, that it takes for the reinforcement fleet to be regenerated. If you set this to 0, a reinforcement fleet will be available every day.")
        b.add(.blob(16), 412, "reserved412", "Reserved", group: "Reserved")
        return b.build(type: ty("sÿst"), name: "Star System", related: [])
    }

