        b.add(.enumeration(.w16, signed: true), 1010, "requireGovt", "Require Bits Apply To", group: "Requirements", help: "Which governments the outfit item's Require bits pertain to: -1 Requirements apply in all outfit shops. 128-383 Requirements apply only on stellars belonging to this govt or its allies.", def: -1, opts: [.v("Every outfitter", -1), .r("Govt and allies' stellars", 128, 383, ty("gövt"), nil), .r("Independent, govt and allies", 1128, 1383, ty("gövt"), 128), .r("Everywhere except govt and allies", 2128, 2383, ty("gövt"), 128), .r("Everywhere except independent, govt and allies", 3128, 3383, ty("gövt"), 128)])
