    static func makeWeaponSchema() -> ResourceSchema {
        var b = SchemaBuilder()
        b.add(.i16, 0, "reload", "Reload (frames)", group: "Timing & Damage", help: "The number of frames it takes for one of this weapon to reload. 30 = 1 shot/sec. Smaller numbers yield faster reloads.")
        b.add(.i16, 2, "duration", "Duration (frames)", group: "Timing & Damage", help: "The number of frames the weapon's shots travel for before they peter out. 30 = 1 second of life. The number of frames the beam stays onscreen.")
        b.add(.i16, 4, "massDamage", "Mass (Armor) Damage", group: "Timing & Damage")
        b.add(.i16, 6, "energyDamage", "Energy (Shield) Damage", group: "Timing & Damage")
        b.add(.enumeration(.w16, signed: true), 8, "guidance", "Guidance", group: "Guidance", help: "The weapon's guidance mode -1 Unguided projectile 0 Beam weapon (see below) 1 Homing weapon (see Seeker field below) 2 (unused) 3 Turreted beam 4 Turreted, unguided projectile 5 Freefall bomb (launched at 80% of the ship…", def: -1, opts: [.v("Unguided projectile", -1), .v("Beam", 0), .v("Homing", 1), .v("Turreted beam", 3), .v("Turreted unguided projectile", 4), .v("Freefall bomb", 5), .v("Freeflight rocket", 6), .v("Front-quadrant turret", 7), .v("Rear-quadrant turret", 8), .v("Point defense turret", 9), .v("Point defense beam", 10), .v("Carried ship (fighter)", 99)])
        b.add(.i16, 10, "speed", "Shot Speed", group: "Guidance", help: "The weapon's speed (pixels per frame * 100)")
        b.add(.i16, 12, "ammoType", "Ammo Type", group: "Guidance", help: "What kind of ammo the weapon uses -1 Ignored (unlimited ammo) 0-255 Draws ammo from this type of weapon.", def: -1, opts: [.v("Doesn't use ammo", -1), .r("Ammo from weapon (index)", 0, 255, ty("wëap"), 128), .v("Destroys ship when fired", -999), .open("Consumes fuel (1000 + 10 per unit)", -1000, nil, 0)])
        b.add(.ref(ty("spïn"), base: 3000), 14, "graphic", "Graphic", group: "Graphics & Sound", help: "What graphic set to use for this weapon 0-255 Use this graphic set (i.e. spin resources 3000-3255)", def: -1, opts: [.v("None", -1)])
        b.add(.i16, 16, "inaccuracy", "Inaccuracy (degrees)", group: "Graphics & Sound", help: "The weapon's inaccuracy as it leaves the ship (ignored for guidance-10 point defense beams) 0 Fires straight 1 and up Fires with up to this amount of inaccuracy (in degrees)", opts: [.open("Error margin", 0, nil, nil), .open("Fixed offset (unguided only)", -2, nil, 2)])
        b.add(.ref(ty("snd "), base: 200), 18, "sound", "Sound", group: "Graphics & Sound", help: "Which sound to play when the weapon fires -1 Silent but deadly 0-63 Play this sound (snd ID 200-263)", def: -1, opts: [.v("Silent", -1)])
        b.add(.i16, 20, "impact", "Impact", group: "Impact", help: "The magnitude of the impact when the shot hits something 0 No impact 1 and up This amount of impact, which is inversely proportional to the ship's mass. (e.g.", opts: [.open("Repel", 0, nil, nil), .open("Tractor", -1, nil, 1)])
        b.add(.enumeration(.w16, signed: true), 22, "explodeType", "Hit Explosion", group: "Impact", def: -1, opts: [.v("None", -1), .r("Single explosion", 0, 63, ty("bööm"), 128), .r("Explosion plus sparks", 1000, 1063, ty("bööm"), 128)])
        b.add(.i16, 24, "proxRadius", "Proximity Radius", group: "Impact", help: "The radius of the weapon's proximity fuse (useful for unguided missiles and bombs) 0 Weapon requires direct hit to do damage 1 and up This number of pixels of proximity radius Ignored")
        b.add(.i16, 26, "blastRadius", "Blast Radius", group: "Impact", help: "The radius of the weapon's blast effect 0 No blast effect 1 and up This number of pixels of blast radius Ignored")
        b.add(.flags(.w16), 28, "flags", "Flags", group: "Flags", help: "0x0001 Spin the weapon's graphic continuously (rate of frame advance is controlled by the BeamWidth field as detailed below) 0x0002 Weapon fired by second trigger 0x0004 For cycling weapons, always start on the first fra…", bits: [.f(0x1, "Spin graphic continuously"), .f(0x2, "Fired by second trigger"), .f(0x4, "Cycling: always start on first frame"), .f(0x8, "Guided: don't fire at fast ships"), .f(0x10, "Sound loops"), .f(0x20, "Passes through shields"), .f(0x40, "Multiple launchers fire together"), .f(0x80, "Can't be targeted by point defense"), .f(0x100, "Blast doesn't hurt the player"), .f(0x200, "Small smoke"), .f(0x400, "Big smoke"), .f(0x800, "Persistent smoke trail"), .f(0x1000, "Turret: front blind spot"), .f(0x2000, "Turret: side blind spots"), .f(0x4000, "Turret: rear blind spot"), .f(0x8000, "Detonates at end of life (flak)")])
        b.add(.flags(.w16), 30, "seekerFlags", "Seeker Flags", group: "Flags", help: "0x0001 Passes over asteroids 0x0002 Decoyed by asteroids 0x0008 Confused by sensor interference 0x0010 Turns away if jammed 0x0020 Can't fire if ship is ionized 0x4000 Loses lock if target not directly ahead 0x8000 May a…", bits: [.f(0x1, "Passes over asteroids"), .f(0x2, "Decoyed by asteroids"), .f(0x8, "Confused by interference"), .f(0x10, "Turns away if jammed"), .f(0x20, "Can't fire if ship ionized"), .f(0x4000, "Loses lock if target not ahead"), .f(0x8000, "May attack parent if jammed")])
        b.add(.i16, 32, "smokeSet", "Smoke Set", group: "Smoke & Particles", help: "Which cicn set to use for this weapon’s smoke trail, if any. 0 = cicn’s 1000-1007, 1 = 1008-1015, etc.")
        b.add(.i16, 34, "decay", "Decay", group: "Smoke & Particles", help: "How fast to decay each shot’s power -1 or 0 Ignored 1 and up Remove one point of mass & energy damage every time this number of frames goes by (1 frame = 1/30 sec.) If Decay is greater than zero, the beam will \"shrink\" b…")
        b.add(.i16, 36, "particles", "Particles per Frame", group: "Smoke & Particles", help: "Number of particles to generate per frame. Set to zero for no particles")
        b.add(.i16, 38, "partVel", "Particle Velocity", group: "Smoke & Particles", help: "Particle velocity, from 1 to about 200 or so. Experiment to find useful values.")
        b.add(.i16, 40, "partLifeMin", "Particle Life Min", group: "Smoke & Particles", help: "Minimum life of a particle from this weapon, in frames.")
        b.add(.i16, 42, "partLifeMax", "Particle Life Max", group: "Smoke & Particles", help: "Maximum particle life, in frames.")
        b.add(.color, 44, "partColor", "Particle Color", group: "Smoke & Particles", help: "Particle base color, encoded the same as HTML colors. (RRGGBB)")
        b.add(.i16, 48, "beamLength", "Beam Length", group: "Beam", help: "The length of the beam created by this weapon, if applicable.")
        b.add(.i16, 50, "beamWidth", "Beam Width", group: "Beam", help: "Beam width (actually, radius) in pixels. A BeamWidth of 0 will have no center beam, just corona glow. Note: Lightning beams require a BeamWidth or 1 or greater.")
        b.add(.i16, 52, "coronaFalloff", "Corona Falloff", group: "Beam")
        b.add(.color, 54, "beamColor", "Beam Color", group: "Beam", help: "The color of the beam center, encoded as a 24-bit RGB value (00RRGGBB).")
        b.add(.color, 58, "coronaColor", "Corona Color", group: "Beam", help: "The color of the beam corona, encoded as a 24-bit RGB value. Note that since the corona is translucent, it will appear approximately half as bright at its maximum as what you specify in this field.")
        b.add(.i16, 62, "subCount", "Submunition Count", group: "Submunitions", help: "The number of submunitions to create when the shot reaches the end of its life or detonates because something wanders into its proximity radius. Set to 0 or -1 if unused.")
        b.add(.ref(ty("wëap"), base: 0), 64, "subType", "Submunition Weapon", group: "Submunitions", help: "The resource ID of the weapon type to create as submunitions. Anything except beams and fighters is handled.", def: -1, opts: [.v("None", -1)])
        b.add(.i16, 66, "subTheta", "Submunition Spread (degrees)", group: "Submunitions", help: "The angular error of the submunitions as they are launched, as expressed in degrees error from the carrier weapons' heading.")
        b.add(.i16, 68, "subLimit", "Submunition Recursion Limit", group: "Submunitions", help: "If you have defined a recursively-submunitioning weapon (i.e. one which splits into more copies of itself) this field will allow you to limit the number of recursive splits that happen.")
        b.add(.i16, 70, "proxSafety", "Proximity Safety Delay", group: "Submunitions", help: "A time delay for the weapon's proximity fuse, in 30ths of a second. Set to zero for immediate arming on launch.")
        b.add(.flags(.w16), 72, "flags2", "Flags 2", group: "Flags", help: "0x0001 For cycling weapons, keep the graphic on the first frame until the weapon's ProxSafety count has expired 0x0002 For cycling weapons, stop the graphic on the last frame 0x0004 Proximity detonator ignores asteroids…", bits: [.f(0x1, "Cycling: hold first frame until armed"), .f(0x2, "Cycling: stop on last frame"), .f(0x4, "Proximity ignores asteroids"), .f(0x8, "Proximity triggered by non-targets"), .f(0x10, "Submunitions aim at nearest target"), .f(0x20, "Don't launch submunitions at expiry"), .f(0x40, "Don't show ammo quantity"), .f(0x80, "Needs KeyCarried ship aboard"), .f(0x100, "AI won't use"), .f(0x200, "Uses ship's weapon sprite"), .f(0x400, "Planet-type weapon"), .f(0x800, "Hide when out of ammo"), .f(0x1000, "Disables but never destroys"), .f(0x2000, "Beam drawn under ships"), .f(0x4000, "Can fire while cloaked"), .f(0x8000, "x10 damage to asteroids")])
        b.add(.i16, 74, "ionization", "Ionization Charge", group: "Ionization & Hit Effects", help: "The amount of ionization energy to add to the ship that gets hit by this weapon. When a ship is ionized it becomes nearly immobilized until the ionization charge dissipates.")
        b.add(.i16, 76, "hitParticles", "Hit Particle Count", group: "Ionization & Hit Effects", help: "The number of particles to generate when a shot of this type hits a ship or asteroid. Set to zero if unused.")
        b.add(.i16, 78, "hitPartLife", "Hit Particle Life", group: "Ionization & Hit Effects", help: "The average life (in frames) of the hit-particles.")
        b.add(.i16, 80, "hitPartVel", "Hit Particle Velocity", group: "Ionization & Hit Effects", help: "The speed of the hit-particles; a value of 100 is one pixel per frame.")
        b.add(.color, 82, "hitPartColor", "Hit Particle Color", group: "Ionization & Hit Effects", help: "The color of the hit-particles, encoded as a 24-bit HTML color (00RRGGBB)")
        b.add(.i16, 86, "recoil", "Recoil", group: "Recoil & Bursts", help: "The amount of recoil force to apply to the firing ship when this weapon is used: 0 or -1 No recoil Positive values Thrust the ship backwards Negative values Thrust the ship forwards (note that the resulting change to the…")
        b.add(.enumeration(.w16, signed: true), 88, "exitType", "Exit Type", group: "Recoil & Bursts", help: "The type of weapon exit point to use for this weapon: -1 Ignored - weapon will fire from the center of the ship 0 GunPosX/Y 1 TurretPosX/Y 2 GuidedPosX/Y 3 BeamPosX/Y", def: -1, opts: [.v("Ship centre", -1), .v("Gun positions", 0), .v("Turret positions", 1), .v("Guided positions", 2), .v("Beam positions", 3)])
        b.add(.i16, 90, "burstCount", "Shots per Burst", group: "Recoil & Bursts", help: "The number of shots this weapon can fire before having to endure a burst reload. Set to 0 or -1 if unused.")
        b.add(.i16, 92, "burstReload", "Burst Reload (frames)", group: "Recoil & Bursts", help: "The reload time that is imposed when the weapon has fired >= BurstCount shots. Ignored if BurstCount is 0 or -1.")
        b.add(.i16, 94, "jamVuln", "Jam Vulnerability (%)", group: "Jamming", help: "The weapon's vulnerability to the four different types of jamming, from 0 to 100%. Ignored if the weapon is not a guided weapon.", count: 4, stride: 2)
        b.add(.flags(.w16), 102, "flags3", "Flags 3", group: "Flags", help: "0x0001 Weapon will only use ammo at the end of a burst cycle 0x0002 Weapon's shots are translucent 0x0004 Firing ship can't fire another shot of this type until the previous one expires or hits something.", bits: [.f(0x1, "Use ammo only at end of burst"), .f(0x2, "Translucent shots"), .f(0x4, "One shot at a time"), .f(0x10, "Fires from exit nearest target"), .f(0x20, "Exclusive: blocks other weapons")])
        b.add(.i16, 104, "durability", "Shot Durability", group: "Guided / Ammo", help: "For guided weapons, this is how many point defense hits a shot from this weapon can take before it is destroyed. Set to 0 for weapons that are immediately destroyed by any PD hits.")
        b.add(.i16, 106, "guidedTurn", "Guided Turn Rate", group: "Guided / Ammo", help: "For guided weapons, this is the turning speed of the weapon. Higher values yield more maneuverable missiles. Ignored for anything but guided weapons.")
        b.add(.i16, 108, "maxAmmo", "Max Ammo per Launcher", group: "Guided / Ammo", help: "For ammo-using weapons, this is the maximum amount of ammo per each instance of this weapon.")
        b.add(.i16, 110, "liDensity", "Lightning Density", group: "Lightning", help: "For a beam weapon, entering zero in this field will make it a normal, straight beam weapon.")
        b.add(.i16, 112, "liAmplitude", "Lightning Amplitude", group: "Lightning", help: "The amplitude of each zig-zag of a lightning beam, in pixels. Higher numbers yield more jagged-looking beams. Don't overdo this or you will have screen redraw problems.")
        b.add(.color, 114, "ionizeColor", "Ionization Color", group: "Lightning", help: "The color that a ship hit by this weapon will appear after being sufficiently ionized (encoded the same as an HTML color value). A value of 0 here will be interpreted as a default bluish color.")
        b.add(.blob(16), 118, "reserved118", "Reserved", group: "Reserved")
        return b.build(type: ty("wëap"), name: "Weapon", related: [])
    }

